    for t in toks:
        if t.startswith('\x1b['):
            m=re.match(r'\x1b\[38;2;(\d+);(\d+);(\d+)m',t)
            if m: fg=tuple(map(int,m.groups())); continue
            m=re.match(r'\x1b\[48;2;(\d+);(\d+);(\d+)m',t)
            if m: bg=tuple(map(int,m.groups())); continue
