                    s=spans[-1]; spans[-1]=(s[0],col+len(t),s[2]+t,fg,bg)
                else:
                    spans.append((col,col+len(t),t,fg,bg))
                col+=len(t)
    out=[]
    for s in spans:
        if s[4] is not None or s[2].strip():
            out.append(f"[{s[0]}-{s[1]}) {s[2]!r} fg={s[3]} bg={s[4]}")
    if out: print(li, " | ".join(out))
EOF
