use ratatui::prelude::*;
use ratatui::widgets::{Paragraph, Wrap};
use ratatui::text::{Line, Span};

fn dump(buf: &Buffer) {
    for y in 0..buf.area.height {
        let mut s = String::new();
        for x in 0..buf.area.width {
            s.push_str(buf[(x, y)].symbol());
        }
        println!("{:2}|{}|", y, s);
    }
}

fn hints() -> Line<'static> {
    let mut spans = vec![];
    let items = [("hjkl","move cursor"),("f/b","scroll"),("enter/esc","zoom"),("/","search"),("#","search like cursor"),("r","reset"),("tab","switch view"),("q","quit")];
    for (i,(k,d)) in items.iter().enumerate() {
        if i>0 { spans.push(Span::raw(" ")); }
        spans.push(Span::raw("["));
        spans.push(Span::styled(k.to_string(), Style::default().bold().fg(Color::Yellow)));
        spans.push(Span::raw(format!(": {}]", d)));
    }
    Line::from(spans)
}

fn main() {
    for w in [50u16, 100, 180, 60] {
        let area = Rect::new(0,0,w,3);
        let mut buf = Buffer::empty(area);
        let p = Paragraph::new(hints()).alignment(Alignment::Center).wrap(Wrap{trim:true});
        p.render(area, &mut buf);
        println!("W={} wrap trim", w); dump(&buf);
        let mut buf = Buffer::empty(area);
        let p = Paragraph::new(hints()).alignment(Alignment::Center).wrap(Wrap{trim:false});
        p.render(area, &mut buf);
        println!("W={} wrap notrim", w); dump(&buf);
        let mut buf = Buffer::empty(area);
        let p = Paragraph::new(hints()).alignment(Alignment::Center);
        p.render(area, &mut buf);
        println!("W={} nowrap", w); dump(&buf);
    }
    // filename wrap
    for (w, name) in [(14u16, "/tmp/t/one.txt"), (12, "/tmp/t/one.txt"), (15, "/tmp/t/one.txt"), (64, "/tmp/t/longdir_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/f.txt")] {
        let area = Rect::new(0,0,w,3);
        let mut buf = Buffer::empty(area);
        let p = Paragraph::new(name).alignment(Alignment::Center).wrap(Wrap{trim:true});
        println!("w={} line_count={}", w, p.line_count(w));
        p.render(area, &mut buf);
        dump(&buf);
    }
}
EOF
