{"command":"cd /workspace && sed -i '/Cargo.lock/d' .gitignore && cat > src/flame.rs <<'EOF'
//! Data model for folded stack traces and the flame graph tree.

use std::collections::hash_map::DefaultHasher;
use std::collections::HashMap;
use std::hash::{Hash, Hasher};

pub type StackId = usize;

pub const ROOT_ID: StackId = 0;
pub const ROOT_LABEL: &str = "all";

/// A single node of the flame graph tree.
#[derive(Debug, Clone)]
pub struct StackInfo {
    pub id: StackId,
    /// Function name of this frame.  The root has an empty name.
    pub name: String,
    /// Full stack path ("a;b;c").  The root uses the label "all".
    pub full_name: String,
    /// Inclusive sample count.
    pub total: u64,
    /// Exclusive (self) sample count.
    pub own: u64,
    /// Depth in the tree (root is 0).
    pub depth: usize,
    pub parent: Option<StackId>,
    pub children: Vec<StackId>,
    /// Hash of the full name, used to derive a stable color.
    pub hash: u64,
}

impl StackInfo {
    pub fn is_root(&self) -> bool {
        self.id == ROOT_ID
    }

    /// Label used when drawing the frame.
    pub fn label(&self) -> &str {
        if self.is_root() {
            ROOT_LABEL
        } else {
            &self.name
        }
    }
}

/// Aggregated per-function statistics used by the table view.
#[derive(Debug, Clone)]
pub struct FunctionStats {
    pub name: String,
    pub total: u64,
    pub own: u64,
}

#[derive(Debug, Clone)]
pub struct FlameGraph {
    stacks: Vec<StackInfo>,
    max_depth: usize,
    /// Per-level listing of frames, left to right.
    levels: Vec<Vec<StackId>>,
    functions: Vec<FunctionStats>,
}

fn hash_name(name: &str) -> u64 {
    let mut hasher = DefaultHasher::new();
    name.hash(&mut hasher);
    hasher.finish()
}

/// Parse one line of folded stack data: `frame;frame;frame count`.
fn parse_line(line: &str) -> Option<(Vec<&str>, u64)> {
    if line.starts_with('#') {
        return None;
    }
    let (stack, count) = line.rsplit_once(' ')?;
    let count: u64 = count.parse().ok()?;
    Some((stack.split(';').collect(), count))
}

impl FlameGraph {
    pub fn from_string(content: &str, sorted: bool) -> Self {
        let root = StackInfo {
            id: ROOT_ID,
            name: String::new(),
            full_name: ROOT_LABEL.to_string(),
            total: 0,
            own: 0,
            depth: 0,
            parent: None,
            children: Vec::new(),
            hash: hash_name(ROOT_LABEL),
        };
        let mut stacks = vec![root];
        // Lookup of (parent, name) -> child id for fast insertion.
        let mut lookup: HashMap<(StackId, String), StackId> = HashMap::new();

        for line in content.split('\n') {
            let Some((frames, count)) = parse_line(line) else {
                continue;
            };
            stacks[ROOT_ID].total += count;
            let mut current = ROOT_ID;
            let mut full_name = String::new();
            for (i, frame) in frames.iter().enumerate() {
                if i > 0 {
                    full_name.push(';');
                }
                full_name.push_str(frame);
                let key = (current, frame.to_string());
                let child = match lookup.get(&key) {
                    Some(&id) => id,
                    None => {
                        let id = stacks.len();
                        let depth = stacks[current].depth + 1;
                        stacks.push(StackInfo {
                            id,
                            name: frame.to_string(),
                            full_name: full_name.clone(),
                            total: 0,
                            own: 0,
                            depth,
                            parent: Some(current),
                            children: Vec::new(),
                            hash: hash_name(&full_name),
                        });
                        stacks[current].children.push(id);
                        lookup.insert(key, id);
                        id
                    }
                };
                stacks[child].total += count;
                current = child;
            }
            stacks[current].own += count;
        }

        if sorted {
            // Sort children by time spent, largest first.  Ties keep the
            // reverse of their insertion order.
            let totals: Vec<u64> = stacks.iter().map(|s| s.total).collect();
            for stack in stacks.iter_mut() {
                stack.children.sort_by_key(|&c| totals[c]);
                stack.children.reverse();
            }
        }

        let mut graph = FlameGraph {
            stacks,
            max_depth: 0,
            levels: Vec::new(),
            functions: Vec::new(),
        };
        graph.build_levels();
        graph.build_functions();
        graph
    }

    fn build_levels(&mut self) {
        let mut levels: Vec<Vec<StackId>> = Vec::new();
        let mut queue = vec![ROOT_ID];
        // Depth-first traversal keeps the left-to-right order within a level.
        fn visit(graph: &FlameGraph, id: StackId, levels: &mut Vec<Vec<StackId>>) {
            let stack = &graph.stacks[id];
            if levels.len() <= stack.depth {
                levels.resize(stack.depth + 1, Vec::new());
            }
            levels[stack.depth].push(id);
            for &child in &stack.children {
                visit(graph, child, levels);
            }
        }
        while let Some(id) = queue.pop() {
            visit(self, id, &mut levels);
        }
        self.max_depth = levels.len().saturating_sub(1);
        self.levels = levels;
    }

    fn build_functions(&mut self) {
        // name -> (total, own); totals only count the top-most occurrence of
        // a function within a stack so that recursion is not double counted.
        let mut map: HashMap<&str, (u64, u64)> = HashMap::new();
        fn visit<'a>(
            graph: &'a FlameGraph,
            id: StackId,
            path: &mut Vec<&'a str>,
            map: &mut HashMap<&'a str, (u64, u64)>,
        ) {
            let stack = &graph.stacks[id];
            if !stack.is_root() {
                let entry = map.entry(stack.name.as_str()).or_insert((0, 0));
                if !path.contains(&stack.name.as_str()) {
                    entry.0 += stack.total;
                }
                entry.1 += stack.own;
                path.push(stack.name.as_str());
            }
            for &child in &stack.children {
                visit(graph, child, path, map);
            }
            if !stack.is_root() {
                path.pop();
            }
        }
        let mut path = Vec::new();
        visit(self, ROOT_ID, &mut path, &mut map);
        let mut functions: Vec<FunctionStats> = map
            .into_iter()
            .map(|(name, (total, own))| FunctionStats {
                name: name.to_string(),
                total,
                own,
            })
            .collect();
        functions.sort_by(|a, b| a.name.cmp(&b.name));
        self.functions = functions;
    }

    pub fn get(&self, id: StackId) -> &StackInfo {
        &self.stacks[id]
    }

    pub fn root(&self) -> &StackInfo {
        &self.stacks[ROOT_ID]
    }

    pub fn total(&self) -> u64 {
        self.stacks[ROOT_ID].total
    }

    pub fn len(&self) -> usize {
        self.stacks.len()
    }

    pub fn max_depth(&self) -> usize {
        self.max_depth
    }

    pub fn levels(&self) -> &[Vec<StackId>] {
        &self.levels
    }

    pub fn functions(&self) -> &[FunctionStats] {
        &self.functions
    }

    /// Ancestors of a frame, from the root down to (and excluding) the frame.
    pub fn ancestors(&self, id: StackId) -> Vec<StackId> {
        let mut out = Vec::new();
        let mut current = self.stacks[id].parent;
        while let Some(p) = current {
            out.push(p);
            current = self.stacks[p].parent;
        }
        out.reverse();
        out
    }

    /// Whether `ancestor` is an ancestor of (or equal to) `id`.
    pub fn is_ancestor_or_self(&self, ancestor: StackId, id: StackId) -> bool {
        let mut current = Some(id);
        while let Some(c) = current {
            if c == ancestor {
                return true;
            }
            current = self.stacks[c].parent;
        }
        false
    }
}
EOF
echo done"}

