//! Application state and the operations driven by key presses.

use std::collections::{HashMap, HashSet};
use std::time::Duration;

use regex::Regex;

use crate::flame::{FlameGraph, StackId, ROOT_ID};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum View {
    Flamegraph,
    Top,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SortColumn {
    Total,
    Own,
}

/// Position of a frame in the rendered flame graph.
#[derive(Debug, Clone, Copy)]
pub struct FramePos {
    pub id: StackId,
    pub x: u16,
    pub width: u16,
}

/// Layout of all frames, row by row (row index == depth).
#[derive(Debug, Clone, Default)]
pub struct FrameLayout {
    pub rows: Vec<Vec<FramePos>>,
    pub width: u16,
    /// Number of rows that fit in the flame graph area.
    pub page: usize,
}

impl FrameLayout {
    pub fn find(&self, id: StackId) -> Option<(usize, FramePos)> {
        for (row, frames) in self.rows.iter().enumerate() {
            if let Some(f) = frames.iter().find(|f| f.id == id) {
                return Some((row, *f));
            }
        }
        None
    }

    pub fn visible(&self, id: StackId) -> bool {
        self.find(id).map(|(_, f)| f.width > 0).unwrap_or(false)
    }
}

#[derive(Debug, Clone)]
pub struct SearchState {
    pub pattern: String,
    pub regex: Regex,
    /// All frames whose name matches the pattern.
    pub matched: HashSet<StackId>,
    /// Total samples of the top-most matched frames.
    pub matched_total: u64,
}

#[derive(Debug, Clone, Default)]
pub struct TableSelection {
    pub selected: usize,
    pub offset: usize,
}

pub struct App {
    pub flamegraph: FlameGraph,
    pub title: String,
    pub running: bool,
    pub view: View,
    pub selected: StackId,
    pub zoom: Option<StackId>,
    pub scroll: usize,
    pub search: Option<SearchState>,
    /// Text being typed after pressing `/`.
    pub input: Option<String>,
    /// Transient informational message.
    pub info: Option<String>,
    pub debug: bool,
    pub timings: HashMap<String, Duration>,
    pub layout: FrameLayout,
    pub table: TableSelection,
    pub sort_column: SortColumn,
}

impl App {
    pub fn new(flamegraph: FlameGraph, title: String, debug: bool) -> Self {
        App {
            flamegraph,
            title,
            running: true,
            view: View::Flamegraph,
            selected: ROOT_ID,
            zoom: None,
            scroll: 0,
            search: None,
            input: None,
            info: None,
            debug,
            timings: HashMap::new(),
            layout: FrameLayout::default(),
            table: TableSelection::default(),
            sort_column: SortColumn::Own,
        }
    }

    pub fn quit(&mut self) {
        self.running = false;
    }

    pub fn record_timing(&mut self, name: &str, elapsed: Duration) {
        self.timings.insert(name.to_string(), elapsed);
    }

    pub fn zoom_root(&self) -> StackId {
        self.zoom.unwrap_or(ROOT_ID)
    }

    /// Total number of rows of the flame graph.
    pub fn row_count(&self) -> usize {
        self.flamegraph.max_depth() + 1
    }

    // ----------------------------------------------------------------------
    // Layout

    /// Compute the frame positions for the given width.
    pub fn compute_layout(&self, x0: u16, width: u16, page: usize) -> FrameLayout {
        let graph = &self.flamegraph;
        let mut rows: Vec<Vec<FramePos>> = vec![Vec::new(); self.row_count()];
        let zoom_root = self.zoom_root();
        let total = graph.get(zoom_root).total;

        for id in graph
            .ancestors(zoom_root)
            .into_iter()
            .chain(std::iter::once(zoom_root))
        {
            let depth = graph.get(id).depth;
            rows[depth].push(FramePos { id, x: x0, width });
        }

        fn place(
            graph: &FlameGraph,
            id: StackId,
            x: u16,
            total: u64,
            width: u16,
            rows: &mut Vec<Vec<FramePos>>,
        ) {
            let mut cx = x;
            for &child in &graph.get(id).children {
                let c = graph.get(child);
                let w = (c.total as f64 / total as f64 * width as f64) as u16;
                rows[c.depth].push(FramePos {
                    id: child,
                    x: cx,
                    width: w,
                });
                place(graph, child, cx, total, width, rows);
                cx = cx.saturating_add(w);
            }
        }
        place(graph, zoom_root, x0, total, width, &mut rows);

        FrameLayout { rows, width, page }
    }

    // ----------------------------------------------------------------------
    // Scrolling

    fn max_scroll(&self) -> usize {
        self.row_count().saturating_sub(self.layout.page)
    }

    fn after_scroll(&mut self) {
        // Keep the selected frame visible, otherwise select the first visible
        // frame of the top row.
        if let Some((row, pos)) = self.layout.find(self.selected) {
            if pos.width > 0 && row >= self.scroll && row < self.scroll + self.layout.page {
                return;
            }
        }
        if let Some(frames) = self.layout.rows.get(self.scroll) {
            if let Some(first) = frames.iter().find(|f| f.width > 0) {
                self.selected = first.id;
            }
        }
    }

    fn ensure_selected_visible(&mut self) {
        if let Some((row, _)) = self.layout.find(self.selected) {
            if row < self.scroll {
                self.scroll = row;
            } else if self.layout.page > 0 && row >= self.scroll + self.layout.page {
                self.scroll = row + 1 - self.layout.page;
            }
        }
    }

    pub fn scroll_down(&mut self) {
        self.scroll = (self.scroll + self.layout.page).min(self.max_scroll());
        self.after_scroll();
    }

    pub fn scroll_up(&mut self) {
        self.scroll = self.scroll.saturating_sub(self.layout.page);
        self.after_scroll();
    }

    pub fn scroll_bottom(&mut self) {
        self.scroll = self.max_scroll();
        self.after_scroll();
    }

    pub fn scroll_top(&mut self) {
        self.scroll = 0;
        self.after_scroll();
    }

    // ----------------------------------------------------------------------
    // Selection

    fn select(&mut self, id: StackId) {
        self.selected = id;
        self.ensure_selected_visible();
    }

    pub fn select_parent(&mut self) {
        if let Some(parent) = self.flamegraph.get(self.selected).parent {
            self.select(parent);
        }
    }

    pub fn select_child(&mut self) {
        let graph = &self.flamegraph;
        let children = &graph.get(self.selected).children;
        let mut best: Option<StackId> = None;
        for &child in children {
            if !self.layout.visible(child) {
                continue;
            }
            match best {
                Some(b) if graph.get(b).total > graph.get(child).total => {}
                _ => best = Some(child),
            }
        }
        if let Some(b) = best {
            self.select(b);
        }
    }

    fn visible_row(&self, row: usize) -> Vec<FramePos> {
        self.layout
            .rows
            .get(row)
            .map(|r| r.iter().copied().filter(|f| f.width > 0).collect())
            .unwrap_or_default()
    }

    pub fn select_next_sibling(&mut self) {
        if let Some((row, _)) = self.layout.find(self.selected) {
            let frames = self.visible_row(row);
            if let Some(i) = frames.iter().position(|f| f.id == self.selected) {
                if let Some(next) = frames.get(i + 1) {
                    self.select(next.id);
                }
            }
        }
    }

    pub fn select_prev_sibling(&mut self) {
        if let Some((row, _)) = self.layout.find(self.selected) {
            let frames = self.visible_row(row);
            if let Some(i) = frames.iter().position(|f| f.id == self.selected) {
                if i > 0 {
                    self.select(frames[i - 1].id);
                }
            }
        }
    }

    // ----------------------------------------------------------------------
    // Zoom

    pub fn zoom_in(&mut self) {
        self.zoom = Some(self.selected);
    }

    pub fn zoom_out(&mut self) {
        if let Some(z) = self.zoom.take() {
            self.selected = z;
        }
    }

    // ----------------------------------------------------------------------
    // Search

    pub fn start_search(&mut self) {
        self.input = Some(String::new());
    }

    pub fn cancel_search_input(&mut self) {
        self.input = None;
    }

    pub fn submit_search_input(&mut self) {
        if let Some(pattern) = self.input.take() {
            self.set_search(&pattern);
        }
    }

    /// Set the search pattern; an empty pattern clears the search.
    pub fn set_search(&mut self, pattern: &str) {
        if pattern.is_empty() {
            self.search = None;
            return;
        }
        match Regex::new(pattern) {
            Ok(regex) => {
                let (matched, matched_total) = self.compute_matches(&regex);
                self.search = Some(SearchState {
                    pattern: pattern.to_string(),
                    regex,
                    matched,
                    matched_total,
                });
            }
            Err(_) => {
                self.info = Some(format!("Invalid regex: {}", pattern));
            }
        }
    }

    fn compute_matches(&self, regex: &Regex) -> (HashSet<StackId>, u64) {
        let graph = &self.flamegraph;
        let mut matched = HashSet::new();
        let mut total = 0;
        fn visit(
            graph: &FlameGraph,
            id: StackId,
            regex: &Regex,
            ancestor_matched: bool,
            matched: &mut HashSet<StackId>,
            total: &mut u64,
        ) {
            let stack = graph.get(id);
            let is_match = regex.is_match(&stack.name);
            if is_match {
                matched.insert(id);
                if !ancestor_matched {
                    *total += stack.total;
                }
            }
            for &child in &stack.children {
                visit(
                    graph,
                    child,
                    regex,
                    ancestor_matched || is_match,
                    matched,
                    total,
                );
            }
        }
        visit(graph, ROOT_ID, regex, false, &mut matched, &mut total);
        (matched, total)
    }

    /// Search for frames with exactly the same name as the selected frame.
    pub fn search_selected(&mut self) {
        let name = self.flamegraph.get(self.selected).name.clone();
        if name.is_empty() {
            return;
        }
        self.set_search(&format!("^{}$", regex::escape(&name)));
    }

    /// Ordered list of visible frames matching the current search.
    fn ordered_matches(&self) -> Vec<(usize, FramePos)> {
        let Some(search) = &self.search else {
            return Vec::new();
        };
        let mut out = Vec::new();
        for (row, frames) in self.layout.rows.iter().enumerate() {
            for f in frames {
                if f.width > 0 && search.matched.contains(&f.id) {
                    out.push((row, *f));
                }
            }
        }
        out
    }

    fn selected_order_key(&self) -> Option<(usize, u16)> {
        self.layout.find(self.selected).map(|(row, f)| (row, f.x))
    }

    pub fn select_next_match(&mut self) {
        let Some(key) = self.selected_order_key() else {
            return;
        };
        let matches = self.ordered_matches();
        if let Some((_, f)) = matches
            .iter()
            .find(|(row, f)| (*row, f.x) > key)
        {
            let id = f.id;
            self.select(id);
        }
    }

    pub fn select_prev_match(&mut self) {
        let Some(key) = self.selected_order_key() else {
            return;
        };
        let matches = self.ordered_matches();
        if let Some((_, f)) = matches
            .iter()
            .rev()
            .find(|(row, f)| (*row, f.x) < key)
        {
            let id = f.id;
            self.select(id);
        }
    }

    // ----------------------------------------------------------------------
    // Reset / views

    pub fn reset(&mut self) {
        self.zoom = None;
        self.selected = ROOT_ID;
        self.scroll = 0;
        self.search = None;
        self.input = None;
        self.table = TableSelection::default();
    }

    pub fn toggle_view(&mut self) {
        self.view = match self.view {
            View::Flamegraph => View::Top,
            View::Top => View::Flamegraph,
        };
    }

    // ----------------------------------------------------------------------
    // Table view

    /// Rows of the table view, filtered and sorted.
    pub fn table_rows(&self) -> Vec<&crate::flame::FunctionStats> {
        let mut rows: Vec<&crate::flame::FunctionStats> = self
            .flamegraph
            .functions()
            .iter()
            .filter(|f| match &self.search {
                Some(s) => s.regex.is_match(&f.name),
                None => true,
            })
            .collect();
        match self.sort_column {
            SortColumn::Total => rows.sort_by_key(|f| f.total),
            SortColumn::Own => rows.sort_by_key(|f| f.own),
        }
        rows.reverse();
        rows
    }

    pub fn table_len(&self) -> usize {
        self.table_rows().len()
    }

    pub fn table_down(&mut self) {
        let len = self.table_len();
        if len > 0 && self.table.selected + 1 < len {
            self.table.selected += 1;
        }
    }

    pub fn table_up(&mut self) {
        self.table.selected = self.table.selected.saturating_sub(1);
    }

    pub fn table_page_down(&mut self, page: usize) {
        let len = self.table_len();
        if len == 0 {
            return;
        }
        self.table.selected = (self.table.selected + page).min(len - 1);
        self.table.offset = self.table.selected;
    }

    pub fn table_page_up(&mut self, page: usize) {
        self.table.selected = self.table.selected.saturating_sub(page);
        self.table.offset = self.table.selected;
    }

    pub fn set_sort_column(&mut self, column: SortColumn) {
        self.sort_column = column;
    }

    /// Search for the function selected in the table and switch to the
    /// flame graph view.
    pub fn table_select_function(&mut self) {
        let rows = self.table_rows();
        if let Some(f) = rows.get(self.table.selected) {
            let name = f.name.clone();
            self.set_search(&format!("^{}$", regex::escape(&name)));
            self.view = View::Flamegraph;
        }
    }
}
