//! Rendering of the application state.

use ratatui::layout::{Alignment, Constraint, Rect};
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span, Text};
use ratatui::widgets::{Block, Borders, Cell, Padding, Paragraph, Row, Table, TableState, Wrap};
use ratatui::Frame;

use crate::app::{App, FramePos, SortColumn, View};
use crate::flame::StackId;

const LEFT_WIDTH: u16 = 20;
const RIGHT_TEXT: &str = concat!("flamelens v", env!("CARGO_PKG_VERSION"));

const SELECTED_BG: Color = Color::Rgb(250, 250, 250);
const MATCH_BG: Color = Color::Rgb(10, 35, 150);
const MATCH_FG: Color = Color::Rgb(225, 10, 10);
const DARK_FG: Color = Color::Rgb(10, 10, 10);
const LIGHT_FG: Color = Color::Rgb(225, 225, 225);
const TABLE_HIGHLIGHT_BG: Color = Color::Rgb(65, 65, 65);

fn title_style() -> Style {
    Style::default()
        .fg(Color::Yellow)
        .add_modifier(Modifier::BOLD)
}

fn bold() -> Style {
    Style::default().add_modifier(Modifier::BOLD)
}

/// A bottom section: a titled separator followed by some text.
struct Section<'a> {
    title: &'static str,
    text: Text<'a>,
}

impl Section<'_> {
    fn height(&self, width: u16) -> u16 {
        let lines = Paragraph::new(self.text.clone())
            .wrap(Wrap { trim: true })
            .line_count(width);
        1 + lines as u16
    }

    fn render(&self, area: Rect, frame: &mut Frame) {
        let block = Block::new()
            .borders(Borders::TOP)
            .title(Span::styled(self.title, title_style()));
        let paragraph = Paragraph::new(self.text.clone())
            .wrap(Wrap { trim: true })
            .block(block);
        frame.render_widget(paragraph, area);
    }
}

/// Distribute `avail` rows among items that would like `needs` rows each.
/// When there is not enough space the available rows are shared as evenly as
/// possible, earlier items getting the remainder.
fn distribute(needs: &[u16], avail: u16) -> Vec<u16> {
    let total: u32 = needs.iter().map(|&n| n as u32).sum();
    if total <= avail as u32 {
        return needs.to_vec();
    }
    let mut sizes = vec![0u16; needs.len()];
    let mut remaining = avail;
    loop {
        let active: Vec<usize> = (0..needs.len()).filter(|&i| sizes[i] < needs[i]).collect();
        if active.is_empty() || remaining == 0 {
            break;
        }
        let share = remaining / active.len() as u16;
        let extra = remaining % active.len() as u16;
        if share == 0 {
            for &i in active.iter().take(extra as usize) {
                sizes[i] += 1;
                remaining -= 1;
            }
            break;
        }
        for (idx, &i) in active.iter().enumerate() {
            let want = share + if (idx as u16) < extra { 1 } else { 0 };
            let give = want.min(needs[i] - sizes[i]);
            sizes[i] += give;
            remaining -= give;
        }
    }
    sizes
}

fn separator(area: Rect, frame: &mut Frame) {
    if area.height == 0 {
        return;
    }
    frame.render_widget(Block::new().borders(Borders::TOP), area);
}

pub fn render(app: &mut App, frame: &mut Frame) {
    let area = frame.area();
    if area.width == 0 || area.height == 0 {
        return;
    }

    // ------------------------------------------------------------------
    // Header geometry
    let right_width = RIGHT_TEXT.len() as u16;
    let (left_w, mid_w, right_w) = {
        let right_w = right_width.min(area.width);
        let rest = area.width - right_w;
        let left_w = LEFT_WIDTH.min(rest);
        (left_w, rest - left_w, right_w)
    };
    let header_lines = Paragraph::new(app.title.as_str())
        .wrap(Wrap { trim: true })
        .line_count(mid_w.saturating_sub(4)) as u16;
    let top_needed = 2 + header_lines;

    // ------------------------------------------------------------------
    // Bottom sections
    let sections = bottom_sections(app);
    let mut needs: Vec<u16> = sections.iter().map(|s| s.height(area.width)).collect();
    needs.push(2); // key hints
    let bottom_needed: u16 = needs.iter().sum();

    let bottom_h = bottom_needed.min(area.height);
    let top_h = top_needed.min(area.height - bottom_h);
    let main_h = area.height - top_h - bottom_h;

    // ------------------------------------------------------------------
    // Top: separator, header, separator
    let sep1_h = top_h.min(1);
    let sep2_h = (top_h - sep1_h).min(1);
    separator(Rect::new(area.x, area.y, area.width, sep1_h), frame);
    separator(
        Rect::new(area.x, area.y + top_h.saturating_sub(1), area.width, sep2_h),
        frame,
    );
    let header_area = Rect::new(area.x, area.y + 1, area.width, top_h.saturating_sub(1));
    render_header(app, header_area, left_w, mid_w, right_w, frame);

    // ------------------------------------------------------------------
    // Main area
    let main_area = Rect::new(area.x, area.y + top_h, area.width, main_h);
    match app.view {
        View::Flamegraph => render_flamegraph(app, main_area, frame),
        View::Top => render_table(app, main_area, frame),
    }

    // ------------------------------------------------------------------
    // Bottom
    let sizes = distribute(&needs, bottom_h);
    let mut y = area.y + top_h + main_h;
    for (i, section) in sections.iter().enumerate() {
        let h = sizes[i];
        if h > 0 {
            section.render(Rect::new(area.x, y, area.width, h), frame);
        }
        y += h;
    }
    let hints_h = sizes[sections.len()];
    if hints_h > 0 {
        render_hints(app, Rect::new(area.x, y, area.width, hints_h), frame);
    }

    // Cursor while typing a search pattern.
    if let Some(input) = &app.input {
        if let Some(idx) = sections.iter().position(|s| s.title == "Search ") {
            let mut sy = area.y + top_h + main_h;
            for s in sizes.iter().take(idx) {
                sy += s;
            }
            if sizes[idx] >= 2 {
                let x = area.x + (input.chars().count() as u16).min(area.width.saturating_sub(1));
                frame.set_cursor_position((x, sy + 1));
            }
        }
    }
}

fn render_header(app: &App, area: Rect, left_w: u16, mid_w: u16, right_w: u16, frame: &mut Frame) {
    if area.height == 0 {
        return;
    }
    let left = match app.view {
        View::Flamegraph => Line::from(vec![
            Span::raw(" "),
            Span::styled("[Flamegraph]", title_style()),
            Span::raw(" | "),
            Span::styled("Top", bold()),
        ]),
        View::Top => Line::from(vec![
            Span::raw(" "),
            Span::styled("Flamegraph", bold()),
            Span::raw(" | "),
            Span::styled("[Top]", title_style()),
        ]),
    };
    let left_area = Rect::new(area.x, area.y, left_w, area.height);
    frame.render_widget(Paragraph::new(left), left_area);

    let mid_area = Rect::new(area.x + left_w, area.y, mid_w, area.height);
    let mid = Paragraph::new(Span::styled(app.title.as_str(), bold()))
        .alignment(Alignment::Center)
        .wrap(Wrap { trim: true });
    frame.render_widget(mid, mid_area);

    let right_area = Rect::new(area.x + left_w + mid_w, area.y, right_w, area.height);
    frame.render_widget(Paragraph::new(Span::styled(RIGHT_TEXT, bold())), right_area);
}

fn percent(count: u64, total: u64) -> f64 {
    count as f64 / total as f64 * 100.0
}

fn frame_info(app: &App, id: StackId) -> String {
    let graph = &app.flamegraph;
