}

fn bottom_sections(app: &App) -> Vec<Section<'static>> {
    let mut sections = Vec::new();
    if let Some(input) = &app.input {
        sections.push(Section {
            title: "Search ",
            text: Text::from(input.clone()),
        });
        return sections;
    }
    if let Some(info) = match_info(app) {
        sections.push(Section {
            title: "Match ",
            text: Text::from(info),
        });
    }
    if app.view == View::Flamegraph {
        sections.push(Section {
            title: "Selected ",
            text: Text::from(frame_info(app, app.selected)),
        });
    }
    if app.debug {
        sections.push(Section {
            title: "Debug ",
            text: Text::from(debug_info(app)),
        });
    }
    if let Some(info) = &app.info {
        sections.push(Section {
            title: "Info ",
            text: Text::from(info.clone()),
        });
    }
    sections
}

fn hint_spans(items: &[(&'static str, &'static str)]) -> Line<'static> {
    let mut spans = Vec::new();
    for (i, (key, desc)) in items.iter().enumerate() {
        if i > 0 {
            spans.push(Span::raw(" "));
        }
        spans.push(Span::raw("["));
        spans.push(Span::styled(*key, title_style()));
        spans.push(Span::raw(format!(": {}]", desc)));
    }
    Line::from(spans)
}

fn render_hints(app: &App, area: Rect, frame: &mut Frame) {
    let line = match app.view {
        View::Flamegraph => {
            let mut items = vec![
                ("hjkl", "move cursor"),
                ("f/b", "scroll"),
                ("enter/esc", "zoom"),
                ("/", "search"),
                ("#", "search like cursor"),
            ];
            if app.search.is_some() {
                items.push(("n/N", "next/prev search"));
            }
            items.push(("r", "reset"));
            items.push(("tab", "switch view"));
            items.push(("q", "quit"));
            hint_spans(&items)
        }
        View::Top => hint_spans(&[
            ("j/k", "move cursor"),
            ("f/b", "scroll"),
            ("1", "sort by total"),
            ("2", "sort by own"),
            ("/", "filter"),
            ("r", "reset"),
            ("tab", "switch view"),
            ("q", "quit"),
        ]),
    };
    let block = Block::new()
        .borders(Borders::TOP)
        .padding(Padding::left(1));
    let paragraph = Paragraph::new(line)
        .alignment(Alignment::Center)
        .block(block);
    frame.render_widget(paragraph, area);
}

