// Flame graph

fn hash_color(hash: u64) -> (u8, u8, u8) {
    let v = hash as f64 / u64::MAX as f64;
    (
        205 + (50.0 * v) as u8,
        (230.0 * v) as u8,
        (55.0 * v) as u8,
    )
}

fn dim((r, g, b): (u8, u8, u8)) -> (u8, u8, u8) {
    (
        (r as f64 * 0.4) as u8,
        (g as f64 * 0.4) as u8,
        (b as f64 * 0.4) as u8,
    )
}

fn contrast_fg((r, g, b): (u8, u8, u8)) -> Color {
    let luminance = 0.2126 * r as f64 + 0.7152 * g as f64 + 0.0722 * b as f64;
    if luminance >= 128.0 {
        DARK_FG
    } else {
        LIGHT_FG
    }
}

fn render_flamegraph(app: &mut App, area: Rect, frame: &mut Frame) {
    let layout = app.compute_layout(area.x, area.width, area.height as usize);
    let zoom_depth = app.flamegraph.get(app.zoom_root()).depth;
    let zoomed = app.zoom.is_some();

    for (row, frames) in layout.rows.iter().enumerate() {
        if row < app.scroll {
            continue;
        }
        let dy = row - app.scroll;
        if dy >= area.height as usize {
            break;
        }
        let y = area.y + dy as u16;
        for pos in frames {
            render_frame(app, pos, y, zoomed && row <= zoom_depth, frame);
        }
    }
    app.layout = layout;
}

fn render_frame(app: &App, pos: &FramePos, y: u16, on_zoom_path: bool, frame: &mut Frame) {
    if pos.width == 0 {
        return;
    }
    let stack = app.flamegraph.get(pos.id);
    let selected = pos.id == app.selected;
    let matched = app
        .search
        .as_ref()
        .map(|s| s.matched.contains(&pos.id))
        .unwrap_or(false);

    let mut bg = if matched {
        (10, 35, 150)
    } else {
        hash_color(stack.hash)
    };
    if on_zoom_path && !selected {
        bg = dim(bg);
    }
    let (bg_color, fg_color) = if selected {
        (SELECTED_BG, DARK_FG)
    } else {
        let _ = MATCH_BG;
        (Color::Rgb(bg.0, bg.1, bg.2), contrast_fg(bg))
    };
    let style = Style::default().fg(fg_color).bg(bg_color);

    let rect = Rect::new(pos.x, y, pos.width, 1);
    let buf = frame.buffer_mut();
    buf.set_style(rect, style);

    if pos.width == 1 {
        buf.set_string(pos.x, y, ".", style);
        return;
    }

    let label = stack.label();
    let max_chars = (pos.width - 1) as usize;
    let truncated: String = label.chars().take(max_chars).collect();
    let mut spans = vec![Span::raw(" ")];
    if matched {
        if let Some(search) = &app.search {
            let mut last = 0;
            for m in search.regex.find_iter(&truncated) {
                if m.start() > last {
                    spans.push(Span::raw(truncated[last..m.start()].to_string()));
                }
                if m.end() > m.start() {
                    spans.push(Span::styled(
                        truncated[m.start()..m.end()].to_string(),
                        Style::default().fg(MATCH_FG),
                    ));
                }
                last = m.end();
            }
            if last < truncated.len() {
                spans.push(Span::raw(truncated[last..].to_string()));
            }
        }
    } else {
        spans.push(Span::raw(truncated));
    }
    let line = Line::from(spans);
    buf.set_line(pos.x, y, &line, pos.width);
    // Make sure the background style covers the whole frame.
    buf.set_style(rect, Style::default().bg(bg_color));
}

// ----------------------------------------------------------------------------
// Table view

fn render_table(app: &mut App, area: Rect, frame: &mut Frame) {
    let total = app.flamegraph.total();
    let rows_data: Vec<(String, String, String)> = app
        .table_rows()
        .iter()
        .map(|f| {
            (
                format!("{} ({:.2}%)", f.total, percent(f.total, total)),
                format!("{} ({:.2}%)", f.own, percent(f.own, total)),
                f.name.clone(),
            )
        })
        .collect();
    let total_w = rows_data
        .iter()
        .map(|r| r.0.chars().count() as u16 + 2)
        .max()
        .unwrap_or(0);
    let own_w = rows_data
        .iter()
        .map(|r| r.1.chars().count() as u16 + 2)
        .max()
        .unwrap_or(0);

    let (total_title, own_title) = match app.sort_column {
        SortColumn::Total => ("Total [▼]", "Own"),
        SortColumn::Own => ("Total", "Own [▼]"),
    };
    let header = Row::new(vec![
        Cell::from(total_title),
        Cell::from(own_title),
        Cell::from("Name"),
    ]);
    let rows: Vec<Row> = rows_data
        .into_iter()
        .map(|(t, o, n)| Row::new(vec![Cell::from(t), Cell::from(o), Cell::from(n)]))
        .collect();
    let widths = [
        Constraint::Length(total_w),
        Constraint::Length(own_w),
        Constraint::Min(0),
    ];
    let table = Table::new(rows, widths)
        .header(header)
        .column_spacing(1)
        .row_highlight_style(Style::default().bg(TABLE_HIGHLIGHT_BG));
    let mut state = TableState::default()
        .with_offset(app.table.offset)
        .with_selected(Some(app.table.selected));
    frame.render_stateful_widget(table, area, &mut state);
    app.table.offset = state.offset();
    app.table.page = area.height as usize;
}
