/// Distribute `avail` rows among items that would like `needs` rows each.
/// When there is not enough space the available rows are shared as evenly as
/// possible, earlier items getting the remainder.
fn distribute(needs: &[u16], avail: u16) -> Vec<u16> {
    let total: u32 = needs.iter().map(|&n| n as u32).sum();
    if total <= avail as u32 {
        return needs.to_vec();
    }
    let mut sizes = vec![0u16; needs.len()];
    let mut remaining = avail;
    loop {
        let active: Vec<usize> = (0..needs.len()).filter(|&i| sizes[i] < needs[i]).collect();
        if active.is_empty() || remaining == 0 {
            break;
        }
        let share = remaining / active.len() as u16;
        let extra = remaining % active.len() as u16;
        if share == 0 {
            for &i in active.iter().take(extra as usize) {
                sizes[i] += 1;
                remaining -= 1;
            }
            break;
        }
        for (idx, &i) in active.iter().enumerate() {
            let want = share + if (idx as u16) < extra { 1 } else { 0 };
            let give = want.min(needs[i] - sizes[i]);
            sizes[i] += give;
            remaining -= give;
        }
    }
    sizes
}

