    out=[]
    for s in spans:
        fg,bg,at=s[3]
        if bg is not None or fg is not None or at or s[2].strip():
            a=''.join(sorted(at))
            out.append(f"[{s[0]}-{s[1]}) {s[2]!r} fg={fg} bg={bg}{' '+a if a else ''}")
    if out: print(li, " | ".join(out))
