use Constraint::*;
fn show(label: &str, h: u16, cons: &[Constraint], flex: Flex) {
    let area = Rect::new(0, 0, 60, h);
    let chunks = Layout::vertical(cons.to_vec()).flex(flex).split(area);
    let v: Vec<String> = chunks.iter().map(|r| format!("{}", r.height)).collect();
