            i=0
            while i < len(parts):
                p=parts[i]
                if p=='38' and i+4 < len(parts) and parts[i+1]=='2':
                    fg=tuple(map(int,parts[i+2:i+5])); i+=5; continue
                if p=='48' and i+4 < len(parts) and parts[i+1]=='2':
                    bg=tuple(map(int,parts[i+2:i+5])); i+=5; continue
                if p=='38' and i+2 < len(parts) and parts[i+1]=='5':
                    fg=('idx',int(parts[i+2])); i+=3; continue
                if p=='48' and i+2 < len(parts) and parts[i+1]=='5':
                    bg=('idx',int(parts[i+2])); i+=3; continue
                if p=='0' or p=='': fg=None; bg=None; attrs=set()
                elif p=='39': fg=None
                elif p=='49': bg=None
                elif p=='1': attrs.add('B')
                elif p=='22': attrs.discard('B')
                elif p=='7': attrs.add('R')
                elif p=='27': attrs.discard('R')
                elif p in ('59',): pass
                else: attrs.add('?'+p)
