    out=[]
    for s in spans:
        f,b,at=s[3]
        if b is not None or f is not None or at or s[2].strip():
            a=''.join(sorted(at))
            out.append(f"[{s[0]}-{s[1]}) {s[2]!r} fg={f} bg={b}{' '+a if a else ''}")
    if out: print(li, " | ".join(out))
