/// extra wrapped lines of the sections, the header lines, the separator below
/// the header, the separator at the very top and finally the sections
/// themselves.
fn vertical_layout(height: u16, header_lines: u16, needs: &mut [u16]) -> (u16, u16, Vec<u16>) {
    let mut sep1: u16 = 1;
    let mut sep2: u16 = 1;
    let mut header = header_lines;
    let total = |sep1: u16, header: u16, sep2: u16, needs: &[u16]| -> u32 {
        sep1 as u32 + header as u32 + sep2 as u32 + needs.iter().map(|&n| n as u32).sum::<u32>()
